package it.servizidigitali.gestionebandi.operatore.frontend.dto;

import java.util.Date;
import java.util.List;

public class IntegrazioneRichiestaDTO {

    private long istanzaFormId;
    private String denominazione;
    private Date data;
    private String stato;
    private boolean integrativo;
    private String numeroProtocollo;
    private Date dataProtocollo;
    private String numeroProtocolloUscita;
    private Date dataProtocolloUscita;
    private List<IntegrazioneAllegatoDTO> allegati;
    private Date dataCreazione;
    private Date dataInvio;
    private boolean integrazione;
    private String statoEsecuzione;
    private boolean esecuzioneIntegrazione;
    private boolean codiceFormIntegrazionePresente;

    public long getIstanzaFormId() {
        return istanzaFormId;
    }

    public void setIstanzaFormId(long istanzaFormId) {
        this.istanzaFormId = istanzaFormId;
    }

    public String getDenominazione() {
        return denominazione;
    }

    public void setDenominazione(String denominazione) {
        this.denominazione = denominazione;
    }

    public Date getData() {
        return data;
    }

    public void setData(Date data) {
        this.data = data;
    }

    public String getStato() {
        return stato;
    }

    public void setStato(String stato) {
        this.stato = stato;
    }

    public boolean isIntegrativo() {
        return integrativo;
    }

    public void setIntegrativo(boolean integrativo) {
        this.integrativo = integrativo;
    }

    public List<IntegrazioneAllegatoDTO> getAllegati() {
        return allegati;
    }

    public void setAllegati(List<IntegrazioneAllegatoDTO> allegati) {
        this.allegati = allegati;
    }

	public String getNumeroProtocollo() {
		return numeroProtocollo;
	}

	public void setNumeroProtocollo(String numeroProtocollo) {
		this.numeroProtocollo = numeroProtocollo;
	}

	public Date getDataProtocollo() {
		return dataProtocollo;
	}

	public void setDataProtocollo(Date dataProtocollo) {
		this.dataProtocollo = dataProtocollo;
	}

    public String getNumeroProtocolloUscita() {
        return numeroProtocolloUscita;
    }

    public void setNumeroProtocolloUscita(String numeroProtocolloUscita) {
        this.numeroProtocolloUscita = numeroProtocolloUscita;
    }

    public Date getDataProtocolloUscita() {
        return dataProtocolloUscita;
    }

    public void setDataProtocolloUscita(Date dataProtocolloUscita) {
        this.dataProtocolloUscita = dataProtocolloUscita;
    }

    public Date getDataCreazione() {
        return dataCreazione;
    }

    public void setDataCreazione(Date dataCreazione) {
        this.dataCreazione = dataCreazione;
    }


    public Date getDataInvio() {
        return dataInvio;
    }

    public void setDataInvio(Date dataInvio) {
        this.dataInvio = dataInvio;
    }

    public boolean isIntegrazione() {
        return integrazione;
    }

    public void setIntegrazione(boolean integrazione) {
        this.integrazione = integrazione;
    }

    public String getStatoEsecuzione() { return statoEsecuzione; }

    public void setStatoEsecuzione(String statoEsecuzione) { this.statoEsecuzione = statoEsecuzione; }

    public boolean isEsecuzioneIntegrazione() {
        return esecuzioneIntegrazione;
    }

    public void setEsecuzioneIntegrazione(boolean esecuzioneIntegrazione) {
        this.esecuzioneIntegrazione = esecuzioneIntegrazione;
    }

    public boolean isCodiceFormIntegrazionePresente() {
        return codiceFormIntegrazionePresente;
    }

    public void setCodiceFormIntegrazionePresente(boolean codiceFormIntegrazionePresente) {
        this.codiceFormIntegrazionePresente = codiceFormIntegrazionePresente;
    }
}

