2468	    public List<IntegrazioneDTO> getIntegrazioni(long bandoId, boolean inEsecuzione, long domandaBandoId) {
2469	        List<BandoForm> bandoForms = bandoFormLocalService.getListaBandoFormBando(bandoId);
2470	        List<IntegrazioneDTO> result;
2471	        Bando bando = bandoLocalService.fetchBando(bandoId);
2472	        // TODO ot
2473	
2474	        Stream<BandoForm> stream;
2475	        if (!inEsecuzione) {
2476	            stream = bandoForms.stream().filter(bandoForm -> bandoForm.getTipoForm().isEmpty() || TipoFormEnum.INTEGRAZIONE.name().equals(bandoForm.getTipoForm()));
2477	        }
2478	        else {
2479	            if (bando != null && bando.getAbilitaEsecuzioneIntegrazione()) {
2480	                stream = getBandoFormStreamDaIntegrareByDomandaBandoId(bandoForms, domandaBandoId);
2481	            }
2482	            else {
2483	                stream = bandoForms.stream().filter(bandoForm ->
2484	                        TipoFormEnum.ESECUZIONE_SALDO_INTEGRAZIONE.name().equals(bandoForm.getTipoForm())
2485	                        || TipoFormEnum.ESECUZIONE_ANTICIPO_INTEGRAZIONE.name().equals(bandoForm.getTipoForm())
2486	                        || TipoFormEnum.ESECUZIONE_INTEGRAZIONE.name().equals(bandoForm.getTipoForm()));
2487	            }
2488	
2489	            // In esecuzione, se è presente il disciplinare esecuzione, il soccorso istruttorio deve essere consentito
2490	            // anche senza un'istanza di servizio esecuzione: si includono i form di integrazione esecuzione
2491	            // (ESECUZIONE_INTEGRAZIONE), tra cui la sottoscrizione del disciplinare.
2492	            boolean disciplinareEsecuzionePresente = bandoForms.stream()
2493	                    .anyMatch(bandoForm -> TipoFormEnum.INTEGRAZIONE_OPERATORE_ESECUZIONE.name().equals(bandoForm.getTipoForm()));
2494	            if (disciplinareEsecuzionePresente) {
2495	                Stream<BandoForm> formIntegrazione = bandoForms.stream()
2496	                        .filter(bandoForm -> TipoFormEnum.ESECUZIONE_INTEGRAZIONE_DISCIPLINARE.name().equals(bandoForm.getTipoForm()));
2497	                stream = Stream.concat(stream, formIntegrazione);
2498	            }
2499	        }
2500	
2501	        List<DomandaBandoDatoAggiuntivo> domandaBandoDatoAggiuntivoList = domandaBandoDatoAggiuntivoLocalService.getDomandaBandoDatoAggiuntivoByDomandaBandoIdAndChiave(Collections.singletonList(domandaBandoId), Collections.singletonList("FORM_ESECUZIONE_NON_ABILITATO"));
2502	        Set<String> formDaEscludere = new HashSet<>();
2503	
2504	        if (ListUtil.isNotNull(domandaBandoDatoAggiuntivoList) && ListUtil.isNotEmpty(domandaBandoDatoAggiuntivoList)) {
2505	            formDaEscludere = domandaBandoDatoAggiuntivoList.stream().map(DomandaBandoDatoAggiuntivo::getValore).collect(Collectors.toSet());
2506	        }
2507	
2508	        if (Validator.isNotNull(formDaEscludere) && !formDaEscludere.isEmpty()) {
2509	            Set<String> finalFormDaEscludere = formDaEscludere;
2510	            result = stream.map(bandoForm -> formLocalService.fetchForm(bandoForm.getFormId()))
2511	                    .filter(form -> !form.isPrincipale())
2512	                    .filter(form -> !finalFormDaEscludere.contains(form.getCodice()))
2513	                    .map(this::mapForm).collect(Collectors.toList());
2514	
2515	        } else {
2516	            result = stream.map(bandoForm -> formLocalService.fetchForm(bandoForm.getFormId()))
2517	                    .filter(form -> !form.isPrincipale())
2518	                    .map(this::mapForm).collect(Collectors.toList());
2519	        }
2520	
